-- Aera v30.72 - Assets_20260731 skill/aura database catalog
-- MySQL 5.7 compatible; safe to re-run.
-- Source SWF SHA256: 54ab0ac2693fbdd0afa0491e122bdbc96d942c2e29bbce81d2f54d5e5243f8a0
--
-- IMPORTANT: the SWF contains visual/linkage assets, not authoritative gameplay
-- numbers (damage, mana, cooldown, aura stat/value/duration). This patch therefore
-- imports every exported linkage and creates inert, unassigned skill/aura templates.
-- It does NOT invent mechanical aura effects.

START TRANSACTION;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='skills' AND COLUMN_NAME='AssetLinkage');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `skills` ADD COLUMN `AssetLinkage` varchar(255) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='skills' AND COLUMN_NAME='AssetGroup');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `skills` ADD COLUMN `AssetGroup` varchar(64) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='skills' AND COLUMN_NAME='AssetTemplate');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `skills` ADD COLUMN `AssetTemplate` tinyint(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras' AND COLUMN_NAME='AssetLinkage');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras` ADD COLUMN `AssetLinkage` varchar(255) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras' AND COLUMN_NAME='AssetTemplate');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras` ADD COLUMN `AssetTemplate` tinyint(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras_effects' AND COLUMN_NAME='AssetLinkage');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras_effects` ADD COLUMN `AssetLinkage` varchar(255) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras_effects' AND COLUMN_NAME='AssetTemplate');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras_effects` ADD COLUMN `AssetTemplate` tinyint(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

CREATE TABLE IF NOT EXISTS `aera_asset_symbols` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `CharacterID` int(11) UNSIGNED NOT NULL,
  `Linkage` varchar(255) NOT NULL,
  `Kind` varchar(24) NOT NULL,
  `AssetGroup` varchar(64) NOT NULL DEFAULT '',
  `SlotRef` varchar(8) NOT NULL DEFAULT '',
  `SourceSWF` varchar(128) NOT NULL,
  `SourceSHA256` char(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_aera_asset_symbols_linkage` (`Linkage`),
  KEY `idx_aera_asset_symbols_kind` (`Kind`),
  KEY `idx_aera_asset_symbols_group` (`AssetGroup`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `auras_effects_assets` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `Linkage` varchar(255) NOT NULL,
  `AssetGroup` varchar(64) NOT NULL DEFAULT '',
  `SlotRef` varchar(8) NOT NULL DEFAULT '',
  `SourceSWF` varchar(128) NOT NULL,
  `SourceSHA256` char(64) NOT NULL,
  `AuraID` int(11) UNSIGNED NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_auras_effects_assets_linkage` (`Linkage`),
  KEY `idx_auras_effects_assets_aura` (`AuraID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Every exported SymbolClass linkage from the supplied SWF.

-- Visual effect linkages. These are catalogued separately because the SWF does not encode
-- AuraID / Stat / Value / Type mechanics needed by `auras_effects`.

-- Asset-backed skill templates. They are intentionally UNASSIGNED (no skills_assign rows)
-- and mechanically inert until you configure them in Admin/DB.

-- Aura visual templates from exported linkages. No fake stat effects are inserted.

-- Reassert the existing Aera/Warlord aura mechanics so this import never downgrades them.
UPDATE `skills` SET `Damage`=0.00,`Target`='s' WHERE `Name` IN ('Prepared Strike','On Guard','Fortune');
UPDATE `auras` SET `Duration`=30,`Category`='none',`Chance`=1.00 WHERE `Name`='Prepared Strike';
UPDATE `auras` SET `Duration`=5,`Category`='none',`Chance`=1.00 WHERE `Name`='On Guard';
UPDATE `auras` SET `Duration`=10,`Category`='none',`Chance`=1.00 WHERE `Name`='Fortune';

COMMIT;
